function layout({ title, description, url = '/', active = '', content, noindex = false, language = 'es', alternates = [] }) {
  const canonical = `${site}${url}`;
  const htmlLanguage = language === 'en' ? 'en' : language === 'es-419' ? 'es-419' : 'es-DO';
  const organizationId = `${site}#organization`;
  const websiteId = `${site}#website`;
  const webpageId = `${canonical}#webpage`;
  const pageLabel = title.split('|')[0].trim();
  const breadcrumb = url === '/' ? null : {
    '@type': 'BreadcrumbList',
    '@id': `${canonical}#breadcrumb`,
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Inicio', item: site },
      { '@type': 'ListItem', position: 2, name: pageLabel, item: canonical },
    ],
  };
  const schema = {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Organization',
        '@id': organizationId,
        name: 'PréstamoPlus',
        legalName: 'PréstamoPlus',
        url: site,
        logo: `${site}/marketing-assets/logo-prestamos-plus.svg`,
        email: 'hola@prestamoplus.com',
        description: 'Software de gestión de préstamos, cartera y cobranza para prestamistas, financieras y cooperativas.',
        areaServed: [
          { '@type': 'Country', name: 'República Dominicana' },
          { '@type': 'Place', name: 'Latinoamérica' },
          { '@type': 'Place', name: 'Mercados internacionales' },
        ],
      },
      { '@type': 'WebSite', '@id': websiteId, name: 'PréstamoPlus', url: site, inLanguage: 'es', publisher: { '@id': organizationId } },
      {
        '@type': 'WebPage',
        '@id': webpageId,
        url: canonical,
        name: title,
        description,
        inLanguage: htmlLanguage,
        isPartOf: { '@id': websiteId },
        about: { '@id': organizationId },
        ...(breadcrumb ? { breadcrumb: { '@id': `${canonical}#breadcrumb` } } : {}),
      },
      {
        '@type': 'SoftwareApplication',
        '@id': `${site}#software`,
        name: 'PréstamoPlus',
        applicationCategory: 'BusinessApplication',
        operatingSystem: 'Web',
        url: site,
        description: 'Plataforma para administrar clientes, préstamos, pagos, mora, cobradores y cartera.',
        provider: { '@id': organizationId },
      },
      ...(breadcrumb ? [breadcrumb] : []),
    ],
  };
  const robots = noindex ? 'noindex,nofollow' : 'index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1';
  const alternateLinks = alternates.map(({ hreflang, href }) => `<link rel="alternate" hreflang="${esc(hreflang)}" href="${esc(href)}">`).join('');
  const ogLocale = language === 'en' ? 'en_US' : language === 'es-419' ? 'es_419' : 'es_DO';
  return `<!doctype html><html lang="${htmlLanguage}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071b2e"><meta name="robots" content="${robots}"><meta name="author" content="PréstamoPlus"><meta name="referrer" content="strict-origin-when-cross-origin"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}">${alternateLinks}<meta property="og:type" content="website"><meta property="og:site_name" content="PréstamoPlus"><meta property="og:locale" content="${ogLocale}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${site}/marketing-assets/logo-prestamos-plus.svg"><meta property="og:image:alt" content="PréstamoPlus, loan management and collections software"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${site}/marketing-assets/logo-prestamos-plus.svg"><link rel="icon" href="/marketing-assets/icono-prestamos-plus.png" type="image/png"><link rel="stylesheet" href="/marketing-assets/site.css"><script type="application/ld+json">${JSON.stringify(schema)}</script></head><body>${header(active, language)}${content}${footer(language)}<script src="/marketing-assets/site.js" defer></script></body></html>`;
}

