function writeRoute(route, html) {
  const dir = route ? path.join(out, route) : out;
  fs.mkdirSync(dir, { recursive: true });
  const renderedHtml = route === '' ? html.replace('</main>', `${multiCurrency()}</main>`) : html;
  fs.writeFileSync(path.join(dir, 'index.html'), renderedHtml);
}
