function multiCurrency() { return `<section class="section currency-section"><div class="container currency-grid"><div><p class="eyebrow">El plus de PréstamoPlus</p><h2>Préstamos en multimoneda, sin mezclar saldos.</h2><p class="muted">Administra capital, cuotas y pagos en la moneda de cada operación. Ideal para prestamistas y financieras con cartera en República Dominicana y Latinoamérica.</p><a class="btn btn-dark" href="/gestion-cartera-prestamos/" style="margin-top:24px">Ver gestión multimoneda <span aria-hidden="true">→</span></a></div><div class="currency-board"><div class="currency-board-top"><span>Divisas disponibles</span><span class="mono">ISO 4217</span></div><div class="currency-flags">${[['🇩🇴','DOP','Peso dominicano','do'],['🇺🇸','USD','Dólar estadounidense','us'],['🇪🇺','EUR','Euro','eu'],['🇲🇽','MXN','Peso mexicano','mx'],['🇬🇹','GTQ','Quetzal','gt'],['🇭🇳','HNL','Lempira','hn'],['🇳🇮','NIO','Córdoba','ni'],['🇨🇷','CRC','Colón','cr'],['🇵🇦','PAB','Balboa','pa'],['🇨🇴','COP','Peso colombiano','co'],['🇵🇪','PEN','Sol','pe'],['🇧🇷','BRL','Real','br'],['🇦🇷','ARS','Peso argentino','ar'],['🇨🇱','CLP','Peso chileno','cl'],['🇨🇦','CAD','Dólar canadiense','ca'],['🇬🇧','GBP','Libra esterlina','gb']].map(([flag,code,name,country]) => `<span class="currency-chip"><b><img src="https://flagcdn.com/w40/${country}.png" alt="Bandera ${country}" loading="lazy" width="28" height="20"> </b><strong>${code}</strong><small>${name}</small></span>`).join('')}</div><p class="currency-note">Cada empresa habilita las divisas que necesita desde su configuración.</p></div></div></section>`; }
